import assert from 'node:assert/strict';
import { readFileSync, readdirSync } from 'node:fs';
import test from 'node:test';

import { lockHashProblems, lockRequirements } from './check-python-lock-hashes.mjs';

const hash = (c) => `--hash=sha256:${c.repeat(64)}`;

test('accepts uv --generate-hashes output', () => {
  const lock = [
    '# This file was autogenerated by uv via the following command:',
    `babel==2.18.0 \\`,
    `    ${hash('a')} \\`,
    `    ${hash('b')}`,
    '    # via courlan',
    `torch==2.14.1+cpu ; platform_machine == 'x86_64' \\`,
    `    ${hash('c')}`,
    '',
  ].join('\n');
  assert.deepEqual(lockHashProblems(lock), []);
  assert.equal(lockRequirements(lock).length, 2);
});

test('rejects unhashed, unpinned, URL and editable requirements', () => {
  const problems = lockHashProblems([
    'babel==2.18.0',
    `requests>=2 \\\n    ${hash('a')}`,
    `en-core-web-sm @ https://example.test/en_core_web_sm.whl \\\n    ${hash('b')}`,
    '-e ./local-package',
    `./vendor/thing.whl ${hash('c')}`,
  ].join('\n'));
  assert.deepEqual(problems, [
    'babel: missing --hash=sha256',
    'requests: not pinned with ==',
    'en-core-web-sm: direct URL or local path requirement',
    '-e is not allowed in a hashed lock: -e ./local-package',
    './vendor/thing.whl: direct URL or local path requirement',
  ]);
  assert.deepEqual(lockHashProblems('# empty\n'), ['no requirements']);
});

test('every tracked Python lock file is fully hashed', () => {
  for (const dir of ['worker', 'scripts']) {
    const directory = new URL(`../${dir}/`, import.meta.url);
    for (const file of readdirSync(directory).filter(name => name.endsWith('.lock.txt'))) {
      assert.deepEqual(lockHashProblems(readFileSync(new URL(file, directory), 'utf8')), [], `${dir}/${file}`);
    }
  }
});

test('the worker supply-chain workflow regenerates locks with hashes and enforces them', () => {
  const workflow = readFileSync(new URL('../.github/workflows/worker-supply-chain.yml', import.meta.url), 'utf8');
  const compiles = workflow.split('\n').filter(line => line.includes('uv pip compile'));
  assert.ok(compiles.length >= 4, 'expected worker and installer lock regeneration');
  for (const line of compiles) assert.match(line, /--generate-hashes/);
  assert.match(workflow, /node scripts\/check-python-lock-hashes\.mjs/);
});
